# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

OPEN = parse_span("09:00-17:00")

def gaps_for(*texts):
    spans = [parse_span(item) for item in texts]
    return find_gaps(spans, OPEN)

class GapTests(unittest.TestCase):
    def test_gap_between_spans(self):
        result = gaps_for("09:00-12:00", "13:00-17:00")
        want = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(result, want)

    def test_edges_and_overlaps(self):
        result = gaps_for("10:00-12:00", "11:00-15:00")
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)",
            "gap 15:00-17:00 (120 min)"
        ])

    def test_no_spans_is_one_gap(self):
        result = gaps_for()
        want = ["gap 09:00-17:00 (480 min)"]
        self.assertEqual(result, want)

    def test_full_cover_has_no_gaps(self):
        self.assertEqual(gaps_for("09:00-17:00"), [])

    def test_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            gaps_for("08:00-10:00")
        with self.assertRaises(ValueError):
            gaps_for("16:00-18:00")
